package com.eventdrivencommerce.payment.infrastructure.persistence;
import com.eventdrivencommerce.payment.application.port.PaymentRepository; import com.eventdrivencommerce.payment.domain.Payment; import org.springframework.stereotype.Repository; import java.util.Optional; import java.util.UUID;
@Repository class JpaPaymentRepository implements PaymentRepository {private final SpringDataPaymentRepository repository;JpaPaymentRepository(SpringDataPaymentRepository repository){this.repository=repository;}public Payment save(Payment p){var existing=repository.findById(p.id());var entity=existing.orElseGet(()->new PaymentJpaEntity(p));entity.copy(p);return repository.save(entity).domain();}public Optional<Payment>findById(UUID id){return repository.findById(id).map(PaymentJpaEntity::domain);}public Optional<Payment>findByOrderId(UUID id){return repository.findByOrderId(id).map(PaymentJpaEntity::domain);}}
